import { type KeyboardEvent, type ReactNode, type Ref, useEffect, useLayoutEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { MoreVert } from "iconoir-react";
import GlideMenu from "./GlideMenu";

/* ---------------------------------------------------------
 * ACTIONS MENU
 * The "…" of a row or a header: a dots button that opens, over
 * everything, the menu of what can be done to the thing it is on
 * (Rename, Archive, Delete…). One menu wherever the thing shows:
 * the sidebar's rows, a list's rows, a page's header.
 * Keyboard: Enter, Space or ArrowDown open it on the first item,
 * ArrowUp on the last; ArrowUp/ArrowDown, Home/End move; Escape
 * closes it back to its button; Tab closes it.
 * Also the menu's pieces (`MenuRow`, `MenuSeparator`, `MenuPopover`),
 * which the sidebar's foot menu uses too.
 * --------------------------------------------------------- */

/** One thing the menu does. */
export type ActionsMenuItem = { key: string; label: string; icon: ReactNode; danger?: boolean; onSelect: () => void };

/** Where the menu opens from its button: below it, its right edge on the button's (`end`) or its left (`start`). Above when there is no room below. */
export type ActionsMenuPlacement = "bottom-end" | "bottom-start";

/** One row of a menu. */
export function MenuRow({
  icon,
  children,
  trailing,
  onClick,
  height = "h-9",
  danger = false,
  role,
}: {
  icon?: ReactNode;
  children: ReactNode;
  trailing?: ReactNode;
  onClick?: () => void;
  height?: string;
  danger?: boolean;
  role?: "menuitem";
}) {
  return (
    <button
      data-menu-row
      type="button"
      role={role}
      tabIndex={role === "menuitem" ? -1 : undefined}
      onClick={onClick}
      className={`relative z-10 flex ${height} w-full items-center gap-1.5 rounded-[8px] px-2 text-left ${role === "menuitem" ? "outline-none" : ""}`}
    >
      {icon !== undefined && <span className={`flex size-5 shrink-0 items-center justify-center [&_svg]:size-4 ${danger ? "text-red" : "text-ink-2"}`}>{icon}</span>}
      <span className={`min-w-0 flex-1 truncate text-[13.5px] ${danger ? "text-red" : "text-ink"}`}>{children}</span>
      {trailing}
    </button>
  );
}

export function MenuSeparator() {
  return <div role="separator" className="my-1 h-px bg-line" />;
}

/** A menu over everything, anchored at `position`: below a point (`top`), or above one (`bottom`); at `left`, or ending at `right`. */
export function MenuPopover({
  position,
  children,
  width = "w-64",
  label,
  role,
  onKeyDown,
  menuRef,
}: {
  position: { top?: number; bottom?: number; left?: number; right?: number };
  children: ReactNode;
  width?: string;
  label?: string;
  role?: "menu";
  onKeyDown?: (event: KeyboardEvent<HTMLDivElement>) => void;
  menuRef?: Ref<HTMLDivElement>;
}) {
  const above = position.bottom !== undefined;
  const fromRight = position.right !== undefined;
  return createPortal(
    <div
      ref={menuRef}
      data-workspace-menu
      role={role}
      aria-label={label}
      tabIndex={role === undefined ? undefined : -1}
      onKeyDown={onKeyDown}
      className={`fixed z-50 ${width} rounded-[14px] bg-surface p-1.5 shadow-overlay outline-none`}
      style={{
        top: position.top,
        bottom: position.bottom,
        left: position.left,
        right: position.right,
        animation: "pop-in 180ms cubic-bezier(0.23,1,0.32,1) both",
        transformOrigin: `${above ? "bottom" : "top"} ${fromRight ? "right" : "left"}`,
      }}
    >
      <GlideMenu className="flex flex-col gap-px" highlightClassName="inset-x-0 rounded-[8px] bg-hover-2">
        {children}
      </GlideMenu>
    </div>,
    document.body,
  );
}

const ROW_HEIGHT = 37;
const GAP = 4;

/** Where the menu of a button at `rect` opens: below it unless there is no room, then above. */
function placeOf(rect: DOMRect, placement: ActionsMenuPlacement, rows: number): { top?: number; bottom?: number; left?: number; right?: number } {
  const height = rows * ROW_HEIGHT + 12;
  const vertical = rect.bottom + GAP + height > window.innerHeight - 8 && rect.top - GAP - height > 8 ? { bottom: window.innerHeight - rect.top + GAP } : { top: rect.bottom + GAP };
  const horizontal = placement === "bottom-end" ? { right: Math.max(8, window.innerWidth - rect.right) } : { left: Math.max(8, rect.left) };
  return { ...vertical, ...horizontal };
}

/**
 * A dots button and the menu of `actions` it opens. `label` names the button ("Actions for …"); the menu
 * is named after it. Open state is its own, or the caller's (`open`, `onOpenChange`: one menu open at a
 * time in a list). An item chosen closes the menu, then runs.
 */
export function ActionsMenu({
  actions,
  label,
  placement = "bottom-end",
  open: controlled,
  onOpenChange,
  className = "",
  iconSize = 16,
  width = "w-44",
}: {
  actions: readonly ActionsMenuItem[];
  label: string;
  placement?: ActionsMenuPlacement;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** the button's classes (its size, colours, when it shows); `aria-expanded:` styles it open */
  className?: string;
  iconSize?: number;
  width?: string;
}) {
  const [own, setOwn] = useState(false);
  const open = controlled ?? own;
  const [position, setPosition] = useState<{ top?: number; bottom?: number; left?: number; right?: number }>({});
  const button = useRef<HTMLButtonElement>(null);
  const menu = useRef<HTMLDivElement>(null);
  /** Which item gets the focus when the menu opens: the first, the last, or none (opened by a pointer). */
  const focusOnOpen = useRef<"first" | "last" | undefined>(undefined);

  const told = useRef(onOpenChange);
  told.current = onOpenChange;
  const isControlled = controlled !== undefined;
  const setOpen = (next: boolean) => {
    if (!isControlled) setOwn(next);
    told.current?.(next);
  };
  const close = (returnFocus: boolean) => {
    setOpen(false);
    if (returnFocus) button.current?.focus();
  };
  const closeRef = useRef(close);
  closeRef.current = close;

  const show = (focus: "first" | "last" | undefined) => {
    const rect = button.current?.getBoundingClientRect();
    if (rect === undefined) return;
    setPosition(placeOf(rect, placement, actions.length));
    focusOnOpen.current = focus;
    setOpen(true);
  };

  // Opened by the caller (controlled) without a click here: placed from the button.
  useLayoutEffect(() => {
    if (!open) return;
    const rect = button.current?.getBoundingClientRect();
    if (rect !== undefined) setPosition(placeOf(rect, placement, actions.length));
  }, [open, placement, actions.length]);

  // Once per opening: the focus in the menu, and what closes it.
  useEffect(() => {
    if (!open) return;
    const items = [...(menu.current?.querySelectorAll<HTMLElement>('[role="menuitem"]') ?? [])];
    const focus = focusOnOpen.current;
    focusOnOpen.current = undefined;
    if (focus === "first") items[0]?.focus();
    else if (focus === "last") items.at(-1)?.focus();
    else menu.current?.focus();
    const outside = (event: PointerEvent) => {
      const target = event.target as Node;
      if (!menu.current?.contains(target) && !button.current?.contains(target)) closeRef.current(false);
    };
    // The page moving under it (a list scrolled, the window resized): it closes, never floats astray.
    const moved = (event: Event) => {
      if (!(event.target instanceof Node && menu.current?.contains(event.target))) closeRef.current(false);
    };
    document.addEventListener("pointerdown", outside);
    window.addEventListener("resize", moved);
    document.addEventListener("scroll", moved, true);
    return () => {
      document.removeEventListener("pointerdown", outside);
      window.removeEventListener("resize", moved);
      document.removeEventListener("scroll", moved, true);
    };
  }, [open]);

  const onMenuKey = (event: KeyboardEvent<HTMLDivElement>) => {
    const items = [...(menu.current?.querySelectorAll<HTMLElement>('[role="menuitem"]') ?? [])];
    const at = items.indexOf(document.activeElement as HTMLElement);
    const go = (index: number) => {
      event.preventDefault();
      items[(index + items.length) % items.length]?.focus();
    };
    if (event.key === "ArrowDown") go(at + 1);
    else if (event.key === "ArrowUp") go(at < 0 ? items.length - 1 : at - 1);
    else if (event.key === "Home") go(0);
    else if (event.key === "End") go(items.length - 1);
    else if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      close(true);
    } else if (event.key === "Tab") close(false);
  };

  return (
    <>
      <button
        ref={button}
        type="button"
        aria-label={label}
        aria-haspopup="menu"
        aria-expanded={open}
        title={label}
        onClick={(event) => (open ? close(false) : show(event.detail === 0 ? "first" : undefined))}
        onKeyDown={(event) => {
          if (event.key === "ArrowDown" || event.key === "ArrowUp") {
            event.preventDefault();
            show(event.key === "ArrowDown" ? "first" : "last");
          }
        }}
        className={`flex shrink-0 items-center justify-center ${className}`}
      >
        <MoreVert width={iconSize} height={iconSize} strokeWidth={2} />
      </button>
      {open && (
        <MenuPopover position={position} width={width} role="menu" label={label} onKeyDown={onMenuKey} menuRef={menu}>
          {actions.map((action) => (
            <MenuRow
              key={action.key}
              role="menuitem"
              icon={action.icon}
              danger={action.danger === true}
              onClick={() => {
                close(false);
                action.onSelect();
              }}
            >
              {action.label}
            </MenuRow>
          ))}
        </MenuPopover>
      )}
    </>
  );
}

import type { ReactNode } from "react";
import { capitalizeFirst } from "@/lib/format";

export type BadgeTone = "neutral" | "green" | "orange" | "red" | "accent";

/**
 * A small badge on the shared `.badge` classes (index.css): 18px, 12px text, a 4px radius. `neutral`
 * is quiet (an outline: a method, a channel, a value in prose); the others are tinted from their hue.
 * A state is a `StatusDot`, not a badge.
 */
export function Badge({ children, tone = "neutral", title, className = "" }: { children: ReactNode; tone?: BadgeTone; title?: string; className?: string }) {
  return (
    <span title={title} className={`badge align-middle ${tone === "neutral" ? "badge-outline" : `badge-tint badge-${tone}`} ${className}`}>
      {capitalizeFirst(children)}
    </span>
  );
}

import type { ButtonHTMLAttributes } from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

/*
 * A button on the shared `.btn` classes (index.css): the controls' height (32px, 36px on touch) and
 * radius (8px), so a button beside an input is as tall as it. `primary` is ink, `secondary` an outline,
 * `ghost` and `quiet` only a hover; `sm` is `md` (one height for every control), `xs` the dense one.
 */
export const buttonVariants = cva("btn", {
  variants: {
    variant: {
      primary: "btn-primary",
      secondary: "btn-outline",
      ghost: "btn-ghost",
      accent: "btn-accent",
      danger: "btn-danger",
      /* transparent until hovered, in the ink of the text around it: dense toolbars, a heading's aside */
      quiet: "btn-ghost text-ink-2 hover:text-ink",
    },
    size: {
      xs: "btn-xs",
      sm: "",
      md: "",
    },
  },
  defaultVariants: { variant: "secondary", size: "md" },
});

export type ButtonVariant = NonNullable<VariantProps<typeof buttonVariants>["variant"]>;

export function Button({ variant, size, className, ...props }: ButtonHTMLAttributes<HTMLButtonElement> & VariantProps<typeof buttonVariants>) {
  return <button type="button" className={cn(buttonVariants({ variant, size }), className)} {...props} />;
}

import type { ReactNode } from "react";

/** Monospace token chip, for code values like `agent.runtime`. Beautiful UI's Chip. */
export function Chip({ children, tone = "neutral", className = "" }: { children: ReactNode; tone?: "neutral" | "accent" | "orange"; className?: string }) {
  const tones = {
    neutral: "bg-inset text-ink-2",
    accent: "bg-accent-tint text-accent-ink",
    orange: "bg-orange-tint text-orange",
  };
  return <code className={`inline rounded-md px-1.5 py-0.5 align-[-1px] font-mono text-[12px] leading-none ${tones[tone]} ${className}`}>{children}</code>;
}

import { type ReactNode, useEffect, useState } from "react";

/* ---------------------------------------------------------
 * CODE BLOCK
 * Beautiful UI's editor panel, fed by the app: a file's
 * name, a copy button, and its lines numbered and coloured
 * (strings and numbers orange, keywords blue, keys and
 * calls in ink). Lines wrap. `plain`: no colours (a command's
 * output, text in no language).
 * --------------------------------------------------------- */

const KEYWORDS = new Set(["import", "from", "export", "default", "async", "function", "const", "let", "var", "await", "return", "if", "else", "for", "while", "new", "throw", "try", "catch", "null", "true", "false", "undefined"]);
const TOKEN =
  /("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`[^`]*`|-?\b\d+(?:\.\d+)?(?:e[+-]?\d+)?\b|\b(?:import|from|export|default|async|function|const|let|var|await|return|if|else|for|while|new|throw|try|catch|null|true|false|undefined)\b|[A-Za-z_$][\w$]*(?=\s*\())/g;

function highlight(text: string): ReactNode[] {
  const nodes: ReactNode[] = [];
  let last = 0;
  let k = 0;
  for (const m of text.matchAll(TOKEN)) {
    const idx = m.index ?? 0;
    const t = m[0];
    if (idx > last) nodes.push(<span key={k++}>{text.slice(last, idx)}</span>);
    const end = idx + t.length;
    let color: string;
    let weight: number | undefined;
    // a JSON key: a string a colon follows
    if (t.startsWith('"') && /^\s*:/.test(text.slice(end))) {
      color = "var(--ink)";
      weight = 500;
    } else if (/^["'`]/.test(t) || /^-?\d/.test(t)) color = "var(--orange)";
    else if (KEYWORDS.has(t)) color = "var(--accent-ink)";
    else {
      color = "var(--ink)";
      weight = 500;
    }
    nodes.push(
      <span key={k++} style={{ color, fontWeight: weight }}>
        {t}
      </span>,
    );
    last = end;
  }
  if (last < text.length) nodes.push(<span key={k++}>{text.slice(last)}</span>);
  return nodes;
}

function FileIcon() {
  return (
    <svg aria-hidden width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" className="shrink-0 text-ink-3">
      <path d="M17.25 6.75 22.5 12l-5.25 5.25m-10.5 0L1.5 12l5.25-5.25m7.5-3-4.5 16.5" />
    </svg>
  );
}

export default function CodeBlock({
  code,
  filename,
  meta,
  plain = false,
  className = "",
}: {
  code: string;
  filename: string;
  /** after the name: what the code is */
  meta?: ReactNode;
  plain?: boolean;
  className?: string;
}) {
  const [copied, setCopied] = useState(false);
  const lines = code.split("\n");
  // the gutter grows with the line numbers' digits
  const gutter = Math.max(20, String(lines.length).length * 7 + 8);

  useEffect(() => {
    if (!copied) return;
    const timer = setTimeout(() => setCopied(false), 1500);
    return () => clearTimeout(timer);
  }, [copied]);

  const copy = () => {
    navigator.clipboard?.writeText(code).then(
      () => setCopied(true),
      () => undefined,
    );
  };

  return (
    <div className={`w-full overflow-hidden rounded-card bg-surface shadow-card ${className}`}>
      <div className="flex h-11 items-center gap-2 border-b border-line px-4 chat-text-12.5">
        <span className="inline-flex min-w-0 items-center gap-[7px]">
          <FileIcon />
          <span className="truncate font-mono leading-none text-ink">{filename}</span>
        </span>
        {meta !== undefined && <span className="truncate chat-text-12 text-ink-3">{meta}</span>}
        <button
          type="button"
          aria-label="Copy code"
          onClick={copy}
          className={`-mr-1 ml-auto flex h-6 shrink-0 items-center gap-1 rounded-[6px] px-1.5 chat-text-12 font-medium transition-colors duration-100 hover:bg-hover ${copied ? "text-green" : "text-ink-3 hover:text-ink"}`}
        >
          {copied ? (
            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
              <path d="M20 6L9 17l-5-5" />
            </svg>
          ) : (
            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
              <rect x="9" y="9" width="12" height="12" rx="2.5" />
              <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" />
            </svg>
          )}
          {copied ? "Copied" : "Copy"}
        </button>
      </div>

      <div className="py-3 font-mono chat-text-12.5 leading-[1.65] text-ink-2">
        <div className="relative">
          <span className="pointer-events-none absolute inset-y-0 w-px bg-line" style={{ left: gutter }} />
          {lines.map((line, i) => (
            <div key={i} className="grid items-start" style={{ gridTemplateColumns: `${gutter}px minmax(0,1fr)` }}>
              <span className="select-none text-center chat-text-11 text-ink-3">{i + 1}</span>
              <code className="pr-3 pl-2 break-words whitespace-pre-wrap">{plain ? line : highlight(line)}</code>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import { Check, NavArrowDown, Search } from "iconoir-react";
import { type KeyboardEvent, useEffect, useId, useLayoutEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";

/* ---------------------------------------------------------
 * COMBOBOX
 * A select of our own: a trigger like a field (`.control`),
 * and a list over everything with the chosen option checked,
 * a search at its top when there are many, descriptions and
 * group headings. Keyboard: arrows, Home/End, Enter, Escape,
 * type-ahead. The list goes into the dialog the trigger is in
 * (Radix's, or a <dialog>), so focus and clicks stay inside.
 * --------------------------------------------------------- */

export interface ComboboxOption {
  value: string;
  label: string;
  /** a line under the label */
  description?: string;
  /** the heading it is listed under; options of a group stay together, in their order */
  group?: string;
  disabled?: boolean;
}

/** More options than this: a search at the top of the list (`search` decides otherwise). */
const SEARCH_FROM = 7;
const GAP = 4;
const MARGIN = 8;
const MAX_HEIGHT = 320;
const MAX_WIDTH = 420;

const words = (text: string) => text.toLowerCase().split(/\s+/).filter(Boolean);
const matches = (option: ComboboxOption, query: string) => {
  const text = `${option.label} ${option.description ?? ""}`.toLowerCase();
  return words(query).every((word) => text.includes(word));
};

type Place = { top: number; left: number; width: number; maxHeight: number; above: boolean };

export function Combobox({
  value,
  options,
  onChange,
  label,
  placeholder = "Choose",
  disabled = false,
  id,
  className = "",
  search,
  searchPlaceholder = "Search",
  empty = "Nothing matches",
}: {
  value: string;
  options: readonly ComboboxOption[];
  onChange: (value: string) => void;
  /** its accessible name */
  label: string;
  /** shown when no option has `value` */
  placeholder?: string;
  disabled?: boolean;
  /** the trigger's id (a `<label htmlFor>`) */
  id?: string;
  /** the trigger's classes (its width) */
  className?: string;
  /** a search at the top of the list; by default when there are more than six options */
  search?: boolean;
  searchPlaceholder?: string;
  /** said when the search matches nothing */
  empty?: string;
}) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [active, setActive] = useState<string>();
  const [place, setPlace] = useState<Place>();
  const [host, setHost] = useState<Element>();
  const trigger = useRef<HTMLButtonElement>(null);
  const popover = useRef<HTMLDivElement>(null);
  const list = useRef<HTMLDivElement>(null);
  const input = useRef<HTMLInputElement>(null);
  const typed = useRef({ text: "", at: 0 });
  const origin = useRef({ top: 0, left: 0 });
  const listId = useId();
  const searching = search ?? options.length >= SEARCH_FROM;

  const chosen = options.find((option) => option.value === value);
  const shown = useMemo(() => (searching && query.trim() !== "" ? options.filter((option) => matches(option, query)) : [...options]), [options, query, searching]);
  // Grouped in the order each group first appears; options without a group first.
  const groups = useMemo(() => {
    const byGroup = new Map<string | undefined, ComboboxOption[]>();
    for (const option of shown) byGroup.set(option.group, [...(byGroup.get(option.group) ?? []), option]);
    const ungrouped = byGroup.get(undefined);
    byGroup.delete(undefined);
    return [...(ungrouped === undefined ? [] : [[undefined, ungrouped] as const]), ...byGroup];
  }, [shown]);
  const ordered = groups.flatMap(([, each]) => each);
  const enabled = ordered.filter((option) => option.disabled !== true);
  const optionId = (option: ComboboxOption) => `${listId}-${ordered.indexOf(option)}`;

  const show = (seed?: string) => {
    if (disabled) return;
    // Inside a dialog, the list goes into it: a modal keeps its focus and its clicks, and a <dialog> is on top of the page.
    setHost(trigger.current?.closest('dialog, [role="dialog"]') ?? document.body);
    setQuery(searching && seed !== undefined ? seed : "");
    setActive(chosen?.disabled === true ? undefined : chosen?.value);
    setPlace(undefined);
    setOpen(true);
  };
  const close = (refocus: boolean) => {
    setOpen(false);
    if (refocus) trigger.current?.focus();
  };
  const closeRef = useRef(close);
  closeRef.current = close;
  const pick = (option: ComboboxOption) => {
    if (option.disabled === true) return;
    close(true);
    if (option.value !== value) onChange(option.value);
  };

  // The active option: the first enabled one when the search leaves it out.
  useEffect(() => {
    if (open && (active === undefined || !enabled.some((option) => option.value === active))) setActive(enabled[0]?.value);
  }, [open, active, enabled]);

  // Placed under the trigger (above it when there is no room), as wide as it at least. A fixed element
  // inside a transformed dialog is placed from the dialog: measured where (0, 0) lands, and moved from there.
  useLayoutEffect(() => {
    if (!open || popover.current === null || trigger.current === null) return;
    const el = popover.current;
    const rect = trigger.current.getBoundingClientRect();
    const box = host === undefined || host === document.body ? new DOMRect(0, 0, window.innerWidth, window.innerHeight) : host.getBoundingClientRect();
    const bounds = { top: Math.max(box.top, 0) + MARGIN, bottom: Math.min(box.bottom, window.innerHeight) - MARGIN, left: Math.max(box.left, 0) + MARGIN, right: Math.min(box.right, window.innerWidth) - MARGIN };
    // Measured once an opening, while it is still at (0, 0), as wide as its options and not scaled by its entrance.
    let natural = place?.width ?? 0;
    if (place === undefined) {
      const at = el.getBoundingClientRect();
      origin.current = { top: at.top, left: at.left };
      natural = at.width;
    }
    const height = Math.min(el.scrollHeight, MAX_HEIGHT);
    const below = bounds.bottom - rect.bottom - GAP;
    const over = rect.top - GAP - bounds.top;
    const above = below < height && over > below;
    const maxHeight = Math.max(120, Math.min(MAX_HEIGHT, above ? over : below));
    const width = Math.min(Math.max(rect.width, natural, 200), MAX_WIDTH, bounds.right - bounds.left);
    const left = Math.min(Math.max(rect.left, bounds.left), bounds.right - width);
    const top = above ? rect.top - GAP - Math.min(height, maxHeight) : rect.bottom + GAP;
    const next = { top: top - origin.current.top, left: left - origin.current.left, width, maxHeight, above };
    if (place === undefined || Math.abs(next.top - place.top) > 0.5 || Math.abs(next.left - place.left) > 0.5 || next.width !== place.width || next.maxHeight !== place.maxHeight) setPlace(next);
  }, [open, host, place, shown.length]);

  // Once per opening: the focus in the list (or its search), and what closes it.
  useEffect(() => {
    if (!open) return;
    (searching ? input.current : list.current)?.focus({ preventScroll: true });
    const outside = (event: PointerEvent) => {
      const target = event.target as Node;
      if (!popover.current?.contains(target) && !trigger.current?.contains(target)) closeRef.current(false);
    };
    // Escape closes the list, not the dialog around it: taken first, at the window, before the dialog's own listener.
    const escape = (event: globalThis.KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      event.stopPropagation();
      closeRef.current(true);
    };
    const moved = (event: Event) => {
      if (!(event.target instanceof Node && popover.current?.contains(event.target))) closeRef.current(false);
    };
    document.addEventListener("pointerdown", outside);
    window.addEventListener("keydown", escape, true);
    window.addEventListener("resize", moved);
    document.addEventListener("scroll", moved, true);
    return () => {
      document.removeEventListener("pointerdown", outside);
      window.removeEventListener("keydown", escape, true);
      window.removeEventListener("resize", moved);
      document.removeEventListener("scroll", moved, true);
    };
  }, [open, searching]);

  // The active option stays in view: the list scrolls, nothing else (scrollIntoView would scroll the
  // dialog's frame too, overflow hidden or not).
  const activeIndex = ordered.findIndex((option) => option.value === active);
  useEffect(() => {
    const box = list.current;
    const option = document.getElementById(`${listId}-${activeIndex}`);
    if (!open || place === undefined || box === null || option === null) return;
    const at = option.getBoundingClientRect();
    const view = box.getBoundingClientRect();
    if (at.top < view.top) box.scrollTop -= view.top - at.top + 4;
    else if (at.bottom > view.bottom) box.scrollTop += at.bottom - view.bottom + 4;
  }, [open, activeIndex, listId, place]);

  /** Type-ahead: the first option whose label starts with what was typed in the last half second. */
  const typeAhead = (key: string) => {
    const now = Date.now();
    typed.current = { text: now - typed.current.at > 500 ? key : typed.current.text + key, at: now };
    const text = typed.current.text.toLowerCase();
    const found = enabled.find((option) => option.label.toLowerCase().startsWith(text)) ?? enabled.find((option) => option.label.toLowerCase().startsWith(key.toLowerCase()));
    if (found !== undefined) setActive(found.value);
    return found;
  };

  const onListKey = (event: KeyboardEvent<HTMLDivElement>) => {
    const at = enabled.findIndex((option) => option.value === active);
    const go = (index: number) => {
      event.preventDefault();
      const option = enabled[Math.min(Math.max(index, 0), enabled.length - 1)];
      if (option !== undefined) setActive(option.value);
    };
    if (event.key === "ArrowDown") go(at < 0 ? 0 : at + 1);
    else if (event.key === "ArrowUp") go(at < 0 ? enabled.length - 1 : at - 1);
    else if (event.key === "Home" && !searching) go(0);
    else if (event.key === "End" && !searching) go(enabled.length - 1);
    else if (event.key === "PageDown") go(at + 8);
    else if (event.key === "PageUp") go(at - 8);
    else if (event.key === "Enter" || (event.key === " " && !searching)) {
      event.preventDefault();
      const option = enabled[at];
      if (option !== undefined) pick(option);
    } else if (event.key === "Tab") {
      event.preventDefault();
      close(true);
    } else if (!searching && event.key.length === 1 && !event.metaKey && !event.ctrlKey && !event.altKey) typeAhead(event.key);
  };

  const onTriggerKey = (event: KeyboardEvent<HTMLButtonElement>) => {
    if (open) return;
    if (event.key === "ArrowDown" || event.key === "ArrowUp" || event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      show();
    } else if (event.key.length === 1 && !event.metaKey && !event.ctrlKey && !event.altKey) {
      // Typed on the closed trigger: the list opens there (into the search, or at the option).
      event.preventDefault();
      show(event.key);
      if (!searching) typeAhead(event.key);
    }
  };

  const activeOption = ordered.find((option) => option.value === active);
  return (
    <>
      <button
        ref={trigger}
        id={id}
        type="button"
        role="combobox"
        aria-label={label}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={open ? listId : undefined}
        disabled={disabled}
        onClick={() => (open ? close(false) : show())}
        onKeyDown={onTriggerKey}
        className={`control flex min-w-0 cursor-pointer items-center gap-2 pr-2 text-left disabled:cursor-not-allowed ${className}`}
      >
        <span className={`min-w-0 flex-1 truncate ${chosen === undefined ? "text-ink-3" : ""}`}>{chosen?.label ?? placeholder}</span>
        <NavArrowDown width={15} height={15} strokeWidth={2} aria-hidden className={`shrink-0 text-ink-2 transition-transform duration-200 ${open ? "rotate-180" : ""}`} />
      </button>
      {open &&
        host !== undefined &&
        createPortal(
          <div
            ref={popover}
            onKeyDown={onListKey}
            className="fixed z-50 flex flex-col overflow-hidden rounded-[10px] border border-(--control-border) bg-surface text-ink shadow-overlay"
            style={{
              top: place?.top ?? 0,
              left: place?.left ?? 0,
              width: place?.width,
              maxHeight: place?.maxHeight ?? MAX_HEIGHT,
              // unseen until placed, yet focusable (a hidden element takes no focus)
              opacity: place === undefined ? 0 : undefined,
              pointerEvents: place === undefined ? "none" : undefined,
              animation: place === undefined ? undefined : "pop-in 140ms cubic-bezier(0.23,1,0.32,1) both",
              transformOrigin: place?.above === true ? "bottom" : "top",
            }}
          >
            {searching && (
              <div className="flex h-(--control-h) shrink-0 items-center gap-2 border-b border-line px-2.5">
                <Search width={14} height={14} strokeWidth={2} className="shrink-0 text-ink-3" aria-hidden />
                <input
                  ref={input}
                  role="combobox"
                  aria-label={`${label}: search`}
                  aria-autocomplete="list"
                  aria-expanded
                  aria-controls={listId}
                  aria-activedescendant={activeOption === undefined ? undefined : optionId(activeOption)}
                  value={query}
                  onChange={(event) => setQuery(event.target.value)}
                  placeholder={searchPlaceholder}
                  spellCheck={false}
                  autoComplete="off"
                  className="h-full min-w-0 flex-1 bg-transparent text-[14px] text-ink outline-none placeholder:text-ink-3 pointer-coarse:text-[16px]"
                />
              </div>
            )}
            <div
              ref={list}
              id={listId}
              role="listbox"
              aria-label={label}
              tabIndex={searching ? undefined : -1}
              aria-activedescendant={searching || activeOption === undefined ? undefined : optionId(activeOption)}
              className="min-h-0 flex-1 overflow-y-auto overscroll-contain p-1 outline-none"
            >
              {ordered.length === 0 && <p className="px-2 py-2 text-[13px] text-ink-3">{empty}</p>}
              {groups.map(([group, each]) => (
                <div key={group ?? ""} role={group === undefined ? undefined : "group"} aria-label={group}>
                  {group !== undefined && <div className="px-2 pt-2 pb-1 text-[12px] font-medium text-ink-3">{group}</div>}
                  {each.map((option) => {
                    const selected = option.value === value;
                    const isActive = option.value === active;
                    return (
                      <div
                        key={option.value}
                        id={optionId(option)}
                        role="option"
                        aria-selected={selected}
                        aria-disabled={option.disabled === true || undefined}
                        onPointerMove={() => option.disabled !== true && !isActive && setActive(option.value)}
                        onClick={() => pick(option)}
                        className={`flex min-h-8 cursor-pointer items-start gap-2 rounded-[6px] py-1.5 pr-2 pl-1.5 text-[14px] leading-5 ${isActive ? "bg-(--control-hover)" : ""} ${option.disabled === true ? "cursor-not-allowed opacity-50" : ""}`}
                      >
                        <span className="flex h-5 w-4 shrink-0 items-center justify-center text-ink">{selected && <Check width={14} height={14} strokeWidth={2.2} aria-hidden />}</span>
                        <span className="min-w-0 flex-1">
                          <span className="block truncate text-ink">{option.label}</span>
                          {option.description !== undefined && <span className="block text-[12.5px] leading-[1.4] text-ink-3">{option.description}</span>}
                        </span>
                      </div>
                    );
                  })}
                </div>
              ))}
            </div>
          </div>,
          host,
        )}
    </>
  );
}

import type { ReactNode } from "react";

/* ---------------------------------------------------------
 * CONTEXT CARDS
 * Beautiful UI's retrieved chunks, fed by real data: a header
 * with a count, then one card each (a title, a figure, what it
 * says, and its source as a chip that opens it). They enter
 * once, then remain.
 * --------------------------------------------------------- */

export type ContextChunk = {
  key: string;
  title: string;
  /** a short figure at the bar's end: "1,250 characters" */
  meta?: string;
  body: string;
  /** the chip: where it came from */
  source: string;
  /** opens in a new tab */
  href?: string;
  /** a few letters on the chip's mark: "WEB" */
  badge: string;
  /** the mark's colour class: "bg-accent-blue" */
  tone: string;
};

/** The header the harness gives a group of context: its name and a count. */
export function ContextHeader({ title, count }: { title: string; count: ReactNode }) {
  return (
    <div className="flex items-center gap-2 px-0.5" style={{ animation: "fade-in 400ms ease-out both" }}>
      <span className="text-[13px] font-semibold text-ink">{title}</span>
      <span className="inline-flex h-5 items-center rounded-md bg-inset px-1.5 text-[11.5px] font-medium text-ink-2 shadow-hairline tabular-nums">{count}</span>
    </div>
  );
}

function SourceChip({ chunk }: { chunk: ContextChunk }) {
  const inner = (
    <>
      <span className={`flex h-3.5 min-w-3.5 shrink-0 items-center justify-center rounded-[4px] px-0.5 ${chunk.tone} text-[7px] font-bold text-white`}>{chunk.badge}</span>
      <span className="min-w-0 truncate">{chunk.source}</span>
      {chunk.href !== undefined && (
        <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden className="shrink-0">
          <path d="M7 17L17 7M7 7h10v10" />
        </svg>
      )}
    </>
  );
  const className = "inline-flex h-6 max-w-full items-center gap-1.5 rounded-chip bg-inset px-2 text-[12px] font-medium text-ink-2 shadow-btn transition-[background-color] duration-300 hover:bg-hover";
  return chunk.href === undefined ? (
    <span className={className}>{inner}</span>
  ) : (
    <a className={className} href={chunk.href} target="_blank" rel="noreferrer noopener" title={chunk.href}>
      {inner}
    </a>
  );
}

export default function ContextCards({ chunks, header, className = "" }: { chunks: ContextChunk[]; header: string; className?: string }) {
  return (
    <div className={`flex w-full flex-col gap-2 ${className}`}>
      <ContextHeader title={header} count={chunks.length} />
      {chunks.map((chunk, i) => (
        <div key={chunk.key} className="overflow-hidden rounded-card bg-surface shadow-card" style={{ animation: `fade-up 400ms cubic-bezier(0.23,1,0.32,1) ${Math.min(i, 8) * 60}ms both` }}>
          <div className="flex items-center gap-2.5 border-b border-line px-3 py-2.5">
            <span className="flex min-w-0 items-center gap-1.5 text-[13px] font-medium text-ink">
              <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" aria-hidden className="shrink-0">
                <path d="M4 6h16M4 12h16M4 18h10" />
              </svg>
              <span className="truncate" title={chunk.title}>
                {chunk.title}
              </span>
            </span>
            {chunk.meta !== undefined && <span className="ml-auto shrink-0 text-[12px] text-ink-3 tabular-nums">{chunk.meta}</span>}
          </div>
          {chunk.body !== "" && <p className="line-clamp-4 px-3 pt-2 pb-1 text-[12.5px] leading-relaxed text-ink-2 [overflow-wrap:anywhere]">{chunk.body}</p>}
          <div className="px-3 pt-1 pb-3">
            <SourceChip chunk={chunk} />
          </div>
        </div>
      ))}
    </div>
  );
}

import type { MouseEvent, ReactNode } from "react";
import { formatAgo } from "@/lib/format";
import { ActionsMenu, type ActionsMenuItem } from "./ActionsMenu";
import { Badge } from "./Badge";

/* ---------------------------------------------------------
 * CONVERSATION LIST
 * A page's list of conversations, compact (44px rows): a small
 * muted glyph when given (where it came from), the title, a spinner while one runs, a tag, the time
 * of its last activity small and muted on the right, then its
 * "…" menu (`ActionsMenu`), shown on hover or focus (always on
 * touch). The whole row opens it. The dashboard's and the
 * chat's Conversations pages, the same look.
 * --------------------------------------------------------- */

export type ConversationListItem = {
  id: string;
  title: string;
  /** a small muted glyph before the title (where it came from), labelled for a screen reader */
  icon?: ReactNode;
  /** its page, for a new tab; a plain click calls `onOpen` when given */
  href: string;
  /** epoch ms */
  lastActivity?: number | undefined;
  busy?: boolean | undefined;
  /** a quiet tag after the title ("Archived") */
  tag?: string | undefined;
  actions: ActionsMenuItem[];
};

/** A plain left click follows `onOpen`; any other (a new tab) follows the link. */
function follow(event: MouseEvent, onOpen: (() => void) | undefined) {
  if (onOpen === undefined || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
  event.preventDefault();
  onOpen();
}

export function ConversationList({ items, onOpen }: { items: readonly ConversationListItem[]; onOpen?: (id: string) => void }) {
  return (
    <ul className="records-shell flex flex-col divide-y divide-line">
      {items.map((item) => (
        <li key={item.id} className="group/row relative flex h-11 items-center gap-3 pr-1.5 pl-4 transition-colors duration-100 hover:bg-hover has-[a:focus-visible]:bg-hover">
          {item.icon !== undefined && <span className="-mr-1 flex size-4 shrink-0 items-center justify-center text-ink-3 [&_svg]:size-[15px]">{item.icon}</span>}
          <a
            href={item.href}
            title={item.title}
            onClick={(event) => follow(event, onOpen === undefined ? undefined : () => onOpen(item.id))}
            className="min-w-0 flex-1 truncate text-[14px] font-medium text-ink outline-none after:absolute after:inset-0 after:content-['']"
          >
            {item.title}
          </a>
          {item.busy === true && <span aria-label="Running" className="spinner size-3 shrink-0" />}
          {item.tag !== undefined && <Badge className="shrink-0">{item.tag}</Badge>}
          <time className="shrink-0 text-[12px] text-ink-3 tabular-nums" dateTime={item.lastActivity === undefined ? undefined : new Date(item.lastActivity).toISOString()}>
            {formatAgo(item.lastActivity)}
          </time>
          <ActionsMenu
            actions={item.actions}
            label={`Actions for ${item.title}`}
            className="relative z-10 size-7 shrink-0 rounded-[7px] text-ink-3 opacity-0 transition-[opacity,background-color,color] duration-100 group-hover/row:opacity-100 group-has-[a:focus-visible]/row:opacity-100 hover:bg-hover-2 hover:text-ink focus-visible:opacity-100 aria-expanded:bg-hover-2 aria-expanded:text-ink aria-expanded:opacity-100 [@media(hover:none)]:opacity-100"
          />
        </li>
      ))}
    </ul>
  );
}

import type { ReactNode } from "react";

/* ---------------------------------------------------------
 * EMPTY STATE
 * Beautiful UI's SearchList "no results", fed by the app: a
 * glyph in a quiet square, what is (not) there, and a hint.
 * --------------------------------------------------------- */

export default function EmptyState({ icon, title, hint }: { icon?: ReactNode; title: string; hint?: ReactNode }) {
  return (
    <div className="flex flex-col items-center justify-center gap-1 px-4 py-8 text-center" style={{ animation: "fade-in 250ms ease-out both" }}>
      <span className="mb-1.5 flex size-8 items-center justify-center rounded-control bg-inset text-ink-3 shadow-hairline [&_svg]:size-[15px]">
        {icon ?? (
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" aria-hidden>
            <circle cx="11" cy="11" r="7" />
            <path d="M21 21l-4.3-4.3" />
          </svg>
        )}
      </span>
      <span className="text-[13px] font-medium text-ink">{title}</span>
