    </div>
  );
}

import { WarningCircle } from "iconoir-react";
import { type ReactNode, useId } from "react";

/* ---------------------------------------------------------
 * FIELD
 * A label over its control (`.control-label`), a hint or
 * what is wrong under it. The label marks the field
 * required or optional (`FieldMark`, the one place that
 * says how). The control is the caller's: it gets the id,
 * the description's id and the invalid state to put on it.
 * --------------------------------------------------------- */

/** What the control of a `Field` puts on itself (its `<input>`, `<textarea>`, a wrapper's inner input). */
export type FieldControlProps = {
  id: string;
  "aria-describedby"?: string;
  "aria-invalid"?: true;
  required?: true;
};

/**
 * How a label marks its field: required with a red asterisk, optional with a quiet "(optional)";
 * nothing when the form does not say. Every form reads it from here: change it here only.
 */
export function FieldMark({ required }: { required?: boolean }) {
  if (required === undefined) return null;
  if (required) {
    return (
      <span className="text-red" aria-hidden>
        *
      </span>
    );
  }
  return <span className="font-normal text-ink-3">(optional)</span>;
}

/** A field's label: `.control-label`, then its mark. */
export function FieldLabel({ htmlFor, required, children, className = "" }: { htmlFor?: string; required?: boolean; children: ReactNode; className?: string }) {
  return (
    <label htmlFor={htmlFor} className={`control-label inline-flex items-baseline gap-1 ${className}`}>
      {children}
      <FieldMark required={required} />
    </label>
  );
}

/** What is wrong with a field, or a form: in red, with a mark. */
export function FieldError({ id, children }: { id?: string; children: ReactNode }) {
  return (
    <p id={id} role="alert" className="flex items-start gap-1.5 text-[12.5px] leading-[1.5] text-red" style={{ animation: "fade-in 160ms ease both" }}>
      <WarningCircle width={15} height={15} strokeWidth={1.9} className="mt-[1.5px] shrink-0" aria-hidden />
      <span className="min-w-0 [overflow-wrap:anywhere]">{children}</span>
    </p>
  );
}

/**
 * A labelled field: `required` true marks it required (and sets `required` on the control), false
 * optional, absent neither. `hint` is under it until there is an `error`, which replaces it.
 */
export function Field({
  label,
  required,
  hint,
  error,
  id,
  className = "",
  children,
}: {
  label: ReactNode;
  required?: boolean;
  hint?: ReactNode;
  error?: ReactNode;
  /** the control's id (one is made when absent) */
  id?: string;
  className?: string;
  children: (control: FieldControlProps) => ReactNode;
}) {
  const made = useId();
  const controlId = id ?? made;
  const shown = error !== undefined && error !== null && error !== false;
  const described = shown ? `${controlId}-error` : hint !== undefined ? `${controlId}-hint` : undefined;
  return (
    <div className={`flex min-w-0 flex-col gap-1.5 ${className}`}>
      <FieldLabel htmlFor={controlId} required={required}>
        {label}
      </FieldLabel>
      {children({ id: controlId, ...(described !== undefined && { "aria-describedby": described }), ...(shown && { "aria-invalid": true }), ...(required === true && { required: true }) })}
      {shown ? (
        <FieldError id={`${controlId}-error`}>{error}</FieldError>
      ) : (
        hint !== undefined && (
          <p id={`${controlId}-hint`} className="text-[12px] leading-[1.5] text-ink-3">
            {hint}
          </p>
        )
      )}
    </div>
  );
}

/* ---------------------------------------------------------
 * FILTER TABLE
 * Beautiful UI's filter chips, fed by the app: chips with a
 * dot and a count that pick what a table shows. A state in a
 * cell is a `StatusDot`, the same dot beside its label.
 * --------------------------------------------------------- */

export type PillTone = "green" | "orange" | "blue" | "red" | "neutral";

/** The dot of each tone, as the chips show it. */
export const TONE_DOT: Record<PillTone, string> = {
  green: "var(--green)",
  orange: "var(--orange)",
  blue: "var(--accent-blue)",
  red: "var(--red)",
  neutral: "var(--ink-3)",
};

export type Filter<K extends string> = { key: K; label: string; count?: number; tone?: PillTone };

/** Chips that pick one of `filters`; each with its dot (a tone) and its count. */
export function FilterChips<K extends string>({ filters, value, onChange, label }: { filters: Filter<K>[]; value: K; onChange: (key: K) => void; label: string }) {
  return (
    <div role="group" aria-label={label} className="-mx-1 flex items-center gap-1 overflow-x-auto px-1 py-1" style={{ scrollbarWidth: "none" }}>
      {filters.map((filter) => {
        const active = value === filter.key;
        return (
          <button
            key={filter.key}
            type="button"
            aria-pressed={active}
            onClick={() => onChange(filter.key)}
            className={`flex h-6.5 shrink-0 items-center gap-1.5 rounded-chip px-2.5 text-[12px] font-medium transition-[background-color,box-shadow,color] duration-200 ${active ? "bg-surface text-ink shadow-btn" : "text-ink-2 hover:bg-hover"}`}
          >
            {filter.tone !== undefined && <span className="size-1.5 rounded-full" style={{ background: TONE_DOT[filter.tone] }} />}
            {filter.label}
            {filter.count !== undefined && <span className={`rounded-[4px] px-1 text-[10.5px] tabular-nums ${active ? "bg-field text-ink-2" : "text-ink-3"}`}>{filter.count}</span>}
          </button>
        );
      })}
    </div>
  );
}

import { useRef, useState, type ReactNode } from "react";

type GlideMenuProps = {
  children: ReactNode;
  className?: string;
  highlightClassName?: string;
  rowSelector?: string;
};

/** A single hover layer that glides between interactive menu rows. */
export default function GlideMenu({
  children,
  className = "",
  highlightClassName = "inset-x-0 rounded-[8px] bg-hover",
  rowSelector = "[data-menu-row]",
}: GlideMenuProps) {
  const ref = useRef<HTMLDivElement>(null);
  const [box, setBox] = useState<{ top: number; height: number } | null>(null);
  const [visible, setVisible] = useState(false);

  const moveTo = (target: EventTarget | null) => {
    const container = ref.current;
    if (!(target instanceof Element) || !container) return;
    const row = target.closest(rowSelector);
    if (!(row instanceof HTMLElement) || !container.contains(row)) return;
    const containerRect = container.getBoundingClientRect();
    const rowRect = row.getBoundingClientRect();
    setBox({ top: rowRect.top - containerRect.top, height: rowRect.height });
    setVisible(true);
  };

  return (
    <div
      ref={ref}
      onMouseOver={(event) => moveTo(event.target)}
      onMouseLeave={() => setVisible(false)}
      onFocusCapture={(event) => moveTo(event.target)}
      onBlurCapture={(event) => {
        if (!ref.current?.contains(event.relatedTarget as Node | null)) setVisible(false);
      }}
      className={`group/glide-menu relative ${className}`}
    >
      <span
        aria-hidden
        className={`pointer-events-none absolute ${highlightClassName}`}
        style={{
          top: box?.top ?? 0,
          height: box?.height ?? 0,
          opacity: box && visible ? 1 : 0,
          transition:
            "top 220ms cubic-bezier(0.23,1,0.32,1), height 220ms cubic-bezier(0.23,1,0.32,1), opacity 150ms ease",
        }}
      />
      {children}
    </div>
  );
}

import { useEffect, useState } from "react";

/* ---------------------------------------------------------
 * LOADING STATE: pixel-grid loader for long-running work
 *
 *   Drive: square cells, a chevron wavefront driving right
 *   Dots:  the same wavefront, circular cells
 *   Orbit: a comet lapping the grid perimeter
 *
 * Paired with a shimmering label and the time elapsed since
 * `since` (epoch ms; by default since it appeared), in mono
 * tabular figures.
 * --------------------------------------------------------- */

const chevron = Array.from({ length: 9 }, (_, i) => {
  const r = Math.floor(i / 3),
    c = i % 3;
  return (c + Math.abs(r - 1)) * 90;
});

const ORBIT_ORDER = [0, 1, 2, 5, 8, 7, 6, 3];
const orbit = Array.from({ length: 9 }, (_, i) => {
  const k = ORBIT_ORDER.indexOf(i);
  return k === -1 ? null : k * 110;
});

const PATTERNS: Record<string, { delays: (number | null)[]; dur: number; round: boolean }> = {
  Drive: { delays: chevron, dur: 650, round: false },
  Dots: { delays: chevron, dur: 650, round: true },
  Orbit: { delays: orbit, dur: 950, round: false },
};

export function LoaderGrid({ variant = "Dots" }: { variant?: string }) {
  const { delays, dur, round } = PATTERNS[variant] ?? (PATTERNS.Dots as (typeof PATTERNS)[string]);
  return (
    <span aria-hidden className="grid shrink-0 grid-cols-[repeat(3,4px)] gap-[1.5px]">
      {delays.map((delay, index) => (
        <span
          key={index}
          className={`size-[4px] bg-ink ${round ? "rounded-full" : "rounded-[1px]"}`}
          style={{
            opacity: delay === null ? 0.07 : 0.15,
            animation: delay === null ? "none" : `pixel-on ${dur}ms ease-in-out ${delay}ms infinite`,
          }}
        />
      ))}
    </span>
  );
}

function useElapsed(since: number | undefined) {
  const [start] = useState(() => since ?? Date.now());
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 100);
    return () => clearInterval(t);
  }, []);
  const total = Math.max(0, now - start) / 1000;
  if (total < 60) return `${total.toFixed(1)}s`;
  return `${Math.floor(total / 60)}m ${(total % 60).toFixed(1)}s`;
}

export default function LoadingState({ label = "Working", variant = "Dots", since }: { label?: string; variant?: string; since?: number }) {
  const elapsed = useElapsed(since);
  return (
    <div role="status" className="flex w-fit items-center gap-2.5">
      <LoaderGrid variant={variant} />
      <span
        className="bg-clip-text chat-text-13 font-medium text-transparent"
        style={{
          backgroundImage: "linear-gradient(90deg, var(--ink-3) 35%, var(--ink) 50%, var(--ink-3) 65%)",
          backgroundSize: "200% 100%",
          animation: "shimmer-text 1.4s linear infinite",
        }}
      >
        {label}
      </span>
      <span className="font-mono chat-text-12 text-ink-3 tabular-nums">{elapsed}</span>
    </div>
  );
}

import type { ReactNode } from "react";
import { LoaderGrid } from "./LoadingState";

/* ---------------------------------------------------------
 * PAGE
 * An operator's page in the harness's voice: the view's name
 * quiet above what it says now (New chat's two-tone heading),
 * a line of context, then its sections, each a small title
 * with its filters and a table or a panel. It fills the pane
 * and scrolls itself (a view's page with `fill: true`).
 * --------------------------------------------------------- */

export function Page({ eyebrow, title, aside, description, children }: { eyebrow: string; title?: ReactNode; aside?: ReactNode; description?: ReactNode; children?: ReactNode }) {
  return (
    <div className="min-h-0 flex-1 overflow-y-auto">
